(* [comment removed for export] *)
Lemma le4_lit_inj : forall t t' : Z, 0 <= t < 2 ^ 32 -> 0 <= t' < 2 ^ 32 ->
  word_to_le_bytes 4 (Z_to_bv 64 t) = word_to_le_bytes 4 (Z_to_bv 64 t') -> t = t'.
Proof.
  intros t t' Ht Ht' E. change (word_to_le_bytes 4 ?v) with (le4 v) in E.
  apply (f_equal bytes_le_to_Z) in E. rewrite !bytes_le_to_Z_le4 in E.
  rewrite !Z_to_bv_unsigned in E. unfold bv_wrap, bv_modulus in E. cbn [Z.of_N] in E.
  change (2 ^ Z.of_N 64)%Z with (2^64)%Z in E.
  rewrite !(Z.mod_small _ (2 ^ 64)) in E by lia. rewrite !Z.mod_small in E by lia. exact E.
Qed.

