Section TailStmts.
  Context {HCEIL : HeapCeil}.
  Variable H : asr.

  (* [comment removed for export] *)
  Definition atail_usage_stmt : Prop :=
    forall (sp0 : word) (argv : list (list byte)) (s0 : as_St H) (msF0 : machine_state) (mo0 : Model)
           (regs0 : bvmap 5 word) (mem0 : word -> option byte) (B tid can : Z)
           (s : as_St H) (msF : machine_state) (mo : Model) (regs : bvmap 5 word) (mem : word -> option byte),
      valid_argv argv -> AMpre H sp0 argv s0 msF0 mo0 regs0 mem0 B tid can -> length argv <> 2%nat ->
      as_VIS H s msF = mkst regs (Z_to_bv 64 0xa4134) mem (seg_rom bsegs) -> as_AKREL H s (mkCfg msF mo) ->
      getr regs 2 = Z_to_bv 64 (bv_unsigned sp0 - 128) -> getr regs 4 = Z_to_bv 64 0x6617f0 -> getr regs 8 = Z_to_bv 64 2 ->
      getr regs 10 = Z_to_bv 64 (Z.of_nat (length argv)) -> getr regs 11 = Z_to_bv 64 (bv_unsigned sp0 + 8) ->
      mstatics H sp0 tid can mem0 mem ->
      m_fds mo = m_fds mo0 ->
      realizes bsegs (mkCfg msF mo) (t_die (msg_usage (hd [] argv)) (m_fs mo)).

  (* [comment removed for export] *)
  Definition atail_open_stmt : Prop :=
    forall (sp0 : word) (argv : list (list byte)) (s0 : as_St H) (msF0 : machine_state) (mo0 : Model)
           (regs0 : bvmap 5 word) (mem0 : word -> option byte) (B tid can : Z) (a0s path : list byte) (pp : Z)
           (s : as_St H) (msF : machine_state) (mo : Model) (regs : bvmap 5 word) (mem : word -> option byte),
      valid_argv argv -> AMpre H sp0 argv s0 msF0 mo0 regs0 mem0 B tid can -> argv = [a0s; path] ->
      rdn RSEGS mem0 (Z_to_bv 64 (bv_unsigned sp0 + 16)) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 pp)) -> astr_at mem0 sp0 pp path ->
      as_VIS H s msF = mkst regs (Z_to_bv 64 0xa422c) mem (seg_rom bsegs) -> as_AKREL H s (mkCfg msF mo) ->
      getr regs 2 = Z_to_bv 64 (bv_unsigned sp0 - 128) -> getr regs 4 = Z_to_bv 64 0x6617f0 -> getr regs 18 = Z_to_bv 64 pp ->
      mstatics H sp0 tid can mem0 mem ->
      fd_lookup (m_fds mo) (Z_to_bv 64 2) = Some (FdChannel (Z_to_bv 64 2)) ->
      realizes bsegs (mkCfg msF mo) (t_die (msg_cannot_open path) (m_fs mo)).

  (* [comment removed for export] *)
  Definition atail_rderr_stmt : Prop :=
    forall (sp0 : word) (argv : list (list byte)) (s0 : as_St H) (msF0 : machine_state) (mo0 : Model)
           (regs0 : bvmap 5 word) (mem0 : word -> option byte) (B tid can : Z) (a0s path : list byte) (pp : Z)
           (s : as_St H) (msF : machine_state) (mo : Model) (regs : bvmap 5 word) (mem : word -> option byte),
      valid_argv argv -> AMpre H sp0 argv s0 msF0 mo0 regs0 mem0 B tid can -> argv = [a0s; path] ->
      rdn RSEGS mem0 (Z_to_bv 64 (bv_unsigned sp0 + 16)) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 pp)) -> astr_at mem0 sp0 pp path ->
      as_VIS H s msF = mkst regs (Z_to_bv 64 0xa41c8) mem (seg_rom bsegs) -> as_AKREL H s (mkCfg msF mo) ->
      getr regs 2 = Z_to_bv 64 (bv_unsigned sp0 - 128) -> getr regs 4 = Z_to_bv 64 0x6617f0 -> getr regs 18 = Z_to_bv 64 pp ->
      mstatics H sp0 tid can mem0 mem ->
      fd_lookup (m_fds mo) (Z_to_bv 64 2) = Some (FdChannel (Z_to_bv 64 2)) ->
      realizes bsegs (mkCfg msF mo) (t_die (msg_read_error path) (m_fs mo)).
End TailStmts.

