    Lemma Cf_of_aleft : forall k AL cap, 0 <= k <= 10 -> aleft H k <= AL -> 0 <= cap <= 2 ^ 26 -> as_Cf H cap <= AL.
    Proof.
      intros k AL cap Hk HAL Hcap. pose proof (aleft_final H HH sp0 Hvsp k AL Hk HAL) as X. unfold TRC26 in X.
      pose proof (Cf_le26 H HH sp0 cap Hcap). pose proof (Cf_le26 H HH sp0 (2 ^ 26) ltac:(lia)). pose proof (Cm_le26 H HH sp0 (2 ^ 26) ltac:(lia)).
      pose proof (fuzz_cost_mono H HH (2 ^ 26) (2 ^ 26) ltac:(lia)). lia.
    Qed.
    Lemma TR_of_aleft : forall k AL (d : list byte), 0 <= k <= 10 -> aleft H k <= AL ->
      Z.of_nat (length d) < MAX_INPUT -> 6 + hdr_cfg d <= Z.of_nat (length d) -> atr_cost H d <= AL /\ forall AL2 cap, AL2 >= AL - atr_cost H d -> 0 <= cap <= 2 ^ 26 -> as_Cf H cap <= AL2.
    Proof.
      intros k AL d Hk HAL Hd H6. pose proof (aleft_final H HH sp0 Hvsp k AL Hk HAL) as X.
      pose proof (atr_cost_le H HH sp0 Hvsp d Hd H6) as Y.
      pose proof (Cf_le26 H HH sp0 (2 ^ 26) ltac:(lia)) as Z1.
      split; [lia|]. intros AL2 cap H2 Hcap. pose proof (Cf_le26 H HH sp0 cap Hcap). lia.
    Qed.
